/**
 * How the screens reach the service: the call as its dialect serves it, and
 * for an operation that travels in a handshake's envelope, the handshake and
 * the envelope (ADR-145, ADR-161). The standard dialect is the operation's
 * own method and path. The dxlib dialect is a POST at /<operationId> with
 * every parameter in one JSON body, and its one envelope is dxlib's
 * datablock: X25519 shared keys, an Ed25519 signature and AES-256-CBC, all
 * through the Web Crypto API. This module imports nothing, so its tests run
 * on Node as it is.
 */

/** The dialect the service serves its operations in. */
export type Dialect = "standard" | "dxlib";

/** Where the service is, its dialect, and the operation that establishes each handshake. */
export interface TransportSettings {
  readonly service: string;
  readonly dialect: Dialect;
  readonly handshakes: Readonly<Record<string, { readonly operation: string }>>;
  /** The fetch the calls go through; the browser's when left out. */
  readonly fetch?: typeof fetch;
}

/**
 * An operation the screens call: its id, its method and path in the
 * standard dialect, the handshake whose envelope it travels in, and in the
 * dxlib dialect each path parameter's name in the body.
 */
export interface Target {
  readonly operation: string;
  readonly method?: string;
  readonly path: string;
  readonly handshake?: string;
  readonly wire?: Readonly<Record<string, string>>;
  /** The file the operation carries: the request's body on an upload, the answer's on a download (ADR-146). */
  readonly stream?: "upload" | "download";
  /** An upload's media type, the one the design gives its body. */
  readonly mediaType?: string;
}

/** The paginated-list idiom's request names, which the dxlib dialect sends as typed values. */
export interface ListNames {
  readonly page?: string;
  readonly pageSize?: string;
  readonly sort?: string;
  readonly sortField?: string;
  readonly sortDirection?: string;
}

/**
 * What one call sends: the path's parameters by name, the query, the JSON
 * body, extra headers, and for a list the names its request takes.
 */
export interface Ask {
  readonly parameters?: Readonly<Record<string, unknown>>;
  readonly query?: Readonly<Record<string, string>>;
  readonly body?: Readonly<Record<string, unknown>>;
  readonly headers?: Readonly<Record<string, string>>;
  readonly list?: ListNames;
}

/** A value as one path segment; "." and ".." would otherwise move up the path. */
export function segment(value: string): string {
  const encoded = encodeURIComponent(value);
  return encoded === "." || encoded === ".." ? encoded.replaceAll(".", "%2E") : encoded;
}

/** A path with its {parameters} filled. */
export function fill(path: string, parameters: Readonly<Record<string, unknown>>): string {
  return path.replace(/\{([^}]+)\}/g, (_, name: string) => segment(String(parameters[name] ?? "")));
}

const encoder = new TextEncoder();
const decoder = new TextDecoder();

function concat(...parts: readonly Uint8Array[]): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) {
    out.set(p, at);
    at += p.length;
  }
  return out;
}

/** A value with its length before it, four bytes big-endian: dxlib's LV. */
function lv(value: Uint8Array): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(4 + value.length);
  new DataView(out.buffer).setUint32(0, value.length);
  out.set(value, 4);
  return out;
}

/** Values packed in one LV, each an LV inside it, as dxlib's CombineLV packs them. */
function combine(...values: readonly Uint8Array[]): Uint8Array<ArrayBuffer> {
  return lv(concat(...values.map(lv)));
}

/** The value of the LV at the start of bytes; what follows it is ignored, as dxlib ignores it. */
function first(bytes: Uint8Array): Uint8Array<ArrayBuffer> {
  if (bytes.length < 4) {
    throw new Error("the envelope ends before a length");
  }
  const length = new DataView(bytes.buffer, bytes.byteOffset, bytes.length).getUint32(0);
  if (4 + length > bytes.length) {
    throw new Error(`the envelope announces ${length} bytes and holds ${bytes.length - 4}`);
  }
  return bytes.slice(4, 4 + length);
}

/** The LVs one after another in bytes, as dxlib's Expand reads them. */
function expand(bytes: Uint8Array): Uint8Array<ArrayBuffer>[] {
  const out: Uint8Array<ArrayBuffer>[] = [];
  let at = 0;
  while (at < bytes.length) {
    const value = first(bytes.subarray(at));
    out.push(value);
    at += 4 + value.length;
  }
  return out;
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

function fromHex(text: string): Uint8Array<ArrayBuffer> {
  if (text.length % 2 !== 0 || /[^0-9a-f]/i.test(text)) {
    throw new Error("not hex");
  }
  const out = new Uint8Array(text.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(text.slice(2 * i, 2 * i + 2), 16);
  }
  return out;
}

function toBase64(bytes: Uint8Array): string {
  let binary = "";
  for (const b of bytes) {
    binary += String.fromCharCode(b);
  }
  return btoa(binary);
}

function fromBase64(text: string): Uint8Array<ArrayBuffer> {
  return Uint8Array.from(atob(text), (c) => c.charCodeAt(0));
}

function equal(a: Uint8Array, b: Uint8Array): boolean {
  return a.length === b.length && a.every((x, i) => x === b[i]);
}

/** How long dxlib accepts an envelope after it was sealed, its datablock's PayloadUnpackTTL. */
const envelopeLifetime = 5 * 60 * 1000;

/** A handshake held: the index that names it, this side's signing key, the service's, and the two keys the exchange derived. */
export interface Held {
  readonly index: string;
  readonly signingKey: CryptoKey;
  readonly serviceKey: CryptoKey;
  readonly sealKey: CryptoKey;
  readonly openKey: CryptoKey;
}

/**
 * Seals payloads into dxlib's envelope: the payloads packed, in a datablock
 * with the time, a nonce, the handshake's index and the payload's SHA-512,
 * encrypted under the first shared key with the IV before it, signed with
 * this side's key, in hex.
 */
export async function seal(held: Held, payloads: readonly Uint8Array[]): Promise<string> {
  const subtle = globalThis.crypto.subtle;
  const packed = combine(...payloads);
  const time = encoder.encode(new Date().toISOString().replace(/\.\d+Z$/, "Z"));
  const nonce = globalThis.crypto.getRandomValues(new Uint8Array(32));
  const hash = new Uint8Array(await subtle.digest("SHA-512", packed));
  const block = combine(time, nonce, encoder.encode(held.index), packed, hash);
  const iv = globalThis.crypto.getRandomValues(new Uint8Array(16));
  const encrypted = concat(iv, new Uint8Array(await subtle.encrypt({ name: "AES-CBC", iv }, held.sealKey, block)));
  const signature = new Uint8Array(await subtle.sign({ name: "Ed25519" }, held.signingKey, encrypted));
  return toHex(combine(encrypted, signature));
}

/**
 * Opens dxlib's envelope: the service's signature checked, the datablock
 * decrypted under the second shared key, its index, age and hash checked,
 * and the payloads it packs answered.
 */
export async function open(held: Held, data: string): Promise<Uint8Array<ArrayBuffer>[]> {
  const subtle = globalThis.crypto.subtle;
  const [encrypted, signature] = expand(first(fromHex(data)));
  if (encrypted === undefined || signature === undefined) {
    throw new Error("the envelope holds no ciphertext and signature");
  }
  if (!(await subtle.verify({ name: "Ed25519" }, held.serviceKey, signature, encrypted))) {
    throw new Error("the envelope's signature is not the service's");
  }
  if (encrypted.length < 32) {
    throw new Error("the envelope's ciphertext is shorter than an IV and a block");
  }
  const block = new Uint8Array(await subtle.decrypt({ name: "AES-CBC", iv: encrypted.slice(0, 16) }, held.openKey, encrypted.slice(16)));
  const [time, , index, packed, hash] = expand(first(block));
  if (time === undefined || index === undefined || packed === undefined || hash === undefined) {
    throw new Error("the envelope's datablock holds fewer than five parts");
  }
  const sealed = Date.parse(decoder.decode(time));
  if (Number.isNaN(sealed) || Date.now() - sealed > envelopeLifetime) {
    throw new Error("the envelope was sealed more than five minutes ago");
  }
  if (decoder.decode(index) !== held.index) {
    throw new Error("the envelope names another handshake");
  }
  if (!equal(new Uint8Array(await subtle.digest("SHA-512", packed)), hash)) {
    throw new Error("the envelope's payload does not match its hash");
  }
  return expand(first(packed));
}

/** A JSON value as the base64 payload dxlib's envelope carries it in. */
function payload(value: unknown): Uint8Array<ArrayBuffer> {
  return encoder.encode(toBase64(encoder.encode(JSON.stringify(value))));
}

/** A JSON answer as a Response, the status the service gave and its body. */
function answer(status: number, value: unknown): Response {
  const empty = value === undefined || status === 204 || status === 205 || status === 304;
  return new Response(empty ? null : JSON.stringify(value), { status, headers: empty ? {} : { "Content-Type": "application/json" } });
}

/** Whether a plain answer tells the client to establish a new handshake, as dxlib answers a missing, expired or used one. */
function refreshes(value: unknown): boolean {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const v = value as Record<string, unknown>;
  return v.reason === "REFRESH_PREKEY" || (typeof v.type === "string" && /refresh[-_]prekey$/i.test(v.type));
}

/** The members of a query as the dxlib dialect's body takes them: a list's numbers as numbers, its page from 0, its sort as a list, a name[key] as an object. */
function dxlibQuery(query: Readonly<Record<string, string>>, list: ListNames | undefined): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [name, value] of Object.entries(query)) {
    const nested = /^(.+)\[(.+)\]$/.exec(name);
    if (list !== undefined && name === list.page) {
      out[name] = Math.max(0, Number(value) - 1);
    } else if (list !== undefined && name === list.pageSize) {
      out[name] = Number(value);
    } else if (list !== undefined && name === list.sort) {
      const descending = value.startsWith("-");
      out[name] = [{ [list.sortField ?? "field_name"]: descending ? value.slice(1) : value, [list.sortDirection ?? "direction"]: descending ? "desc" : "asc" }];
    } else if (nested !== null) {
      const group = (out[nested[1]] ?? {}) as Record<string, unknown>;
      group[nested[2]] = value;
      out[nested[1]] = group;
    } else {
      out[name] = value;
    }
  }
  if (list?.page !== undefined && !(list.page in out)) {
    out[list.page] = 0;
  }
  return out;
}

/** The calls of one service, each made as its dialect serves it, with the handshakes held between them. */
export interface Transport {
  /**
   * Calls an operation and answers its Response; one in an envelope answers
   * the status and body inside it, and a download answers its bytes as they
   * arrive, plain, whatever its request travelled in.
   */
  call(target: Target, ask?: Ask): Promise<Response>;
  /**
   * Streams a file to an upload operation as the request's body, a Blob
   * read as it is sent or a stream, of the target's media type, and answers
   * its Response. In the dxlib dialect the parameters travel as JSON in the
   * X-Var header beside the body, where dxlib reads an upload's parameters.
   */
  upload(target: Target, file: Blob | ReadableStream<Uint8Array>, ask?: Ask): Promise<Response>;
}

/** The transport of a service. */
export function createTransport(settings: TransportSettings): Transport {
  const send = (input: string, init: RequestInit) => (settings.fetch ?? globalThis.fetch)(input, init);
  const service = settings.service.replace(/\/+$/, "");
  const held = new Map<string, Promise<Held>>();

  async function establish(name: string): Promise<Held> {
    const handshake = settings.handshakes[name];
    if (handshake === undefined) {
      throw new Error(`the screens know no handshake ${name}`);
    }
    const subtle = globalThis.crypto.subtle;
    // The private keys are made unexportable; a public key is exportable whatever the flag says.
    const signing = (await subtle.generateKey({ name: "Ed25519" }, false, ["sign", "verify"])) as CryptoKeyPair;
    const first = (await subtle.generateKey({ name: "X25519" }, false, ["deriveBits"])) as CryptoKeyPair;
    const second = (await subtle.generateKey({ name: "X25519" }, false, ["deriveBits"])) as CryptoKeyPair;
    const raw = async (key: CryptoKey) => toHex(new Uint8Array(await subtle.exportKey("raw", key)));
    const response = await send(service + "/" + handshake.operation, {
      method: "POST",
      credentials: "include",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify({ a0: await raw(signing.publicKey), a1: await raw(first.publicKey), a2: await raw(second.publicKey) }),
    });
    const keys = (await response.json().catch(() => undefined)) as Record<string, unknown> | undefined;
    if (!response.ok || keys === undefined) {
      throw new Error(`${handshake.operation} answered ${response.status} and established no handshake ${name}`);
    }
    const key = (member: string) => {
      const value = keys[member];
      if (typeof value !== "string" || value.length !== 64) {
        throw new Error(`${handshake.operation} answered no 32-byte key ${member} in hex`);
      }
      return fromHex(value);
    };
    const index = keys.i;
    if (typeof index !== "string" || index === "") {
      throw new Error(`${handshake.operation} answered no index i`);
    }
    const serviceKey = await subtle.importKey("raw", key("b0"), { name: "Ed25519" }, false, ["verify"]);
    const shared = async (own: CryptoKey, member: string) =>
      subtle.deriveBits({ name: "X25519", public: await subtle.importKey("raw", key(member), { name: "X25519" }, false, []) } as EcdhKeyDeriveParams, own, 256);
    const sealKey = await subtle.importKey("raw", await shared(first.privateKey, "b1"), { name: "AES-CBC" }, false, ["encrypt"]);
    const openKey = await subtle.importKey("raw", await shared(second.privateKey, "b2"), { name: "AES-CBC" }, false, ["decrypt"]);
    return { index, signingKey: signing.privateKey, serviceKey, sealKey, openKey };
  }

  function holding(name: string, renew: boolean): Promise<Held> {
    let current = held.get(name);
    if (current === undefined || renew) {
      current = establish(name);
      current.catch(() => held.delete(name));
      held.set(name, current);
    }
    return current;
  }

  /** One sealed call: the body in the envelope, the answer opened, or the plain answer dxlib gives when it refuses the envelope. */
  async function sealed(name: string, url: string, body: Record<string, unknown>, headers: Record<string, string>, renew: boolean, stream: boolean): Promise<{ response: Response; refresh: boolean }> {
    const keys = await holding(name, renew);
    const d = await seal(keys, [payload({}), payload(body)]);
    const response = await send(url, { method: "POST", credentials: "include", headers: { ...headers, "Content-Type": "application/json" }, body: JSON.stringify({ i: keys.index, d }) });
    if (stream && !(response.headers.get("Content-Type") ?? "").includes("json")) {
      return { response, refresh: false }; // the file, which leaves the envelope (ADR-145)
    }
    const value = (await response.json().catch(() => undefined)) as Record<string, unknown> | undefined;
    if (typeof value?.d !== "string") {
      return { response: answer(response.status, value), refresh: refreshes(value) };
    }
    const [status, , inner] = await open(keys, value.d);
    if (status === undefined || inner === undefined) {
      throw new Error("the answer's envelope holds no status and body");
    }
    const code = fromBase64(decoder.decode(status));
    if (code.length !== 8) {
      throw new Error("the answer's envelope carries no 8-byte status");
    }
    const text = decoder.decode(fromBase64(decoder.decode(inner)));
    const status64 = new DataView(code.buffer).getBigUint64(0);
    return { response: answer(Number(status64), text.trim() === "" ? undefined : JSON.parse(text)), refresh: false };
  }

  async function call(target: Target, ask: Ask = {}): Promise<Response> {
    const headers: Record<string, string> = { Accept: "application/json, application/problem+json", ...(ask.headers ?? {}) };
    if (settings.dialect === "standard") {
      if (target.handshake !== undefined) {
        throw new Error(`${target.operation} travels in the envelope of handshake ${target.handshake}, which the screens seal in the dxlib dialect only`);
      }
      const query = new URLSearchParams(ask.query ?? {}).toString();
      return send(service + fill(target.path, ask.parameters ?? {}) + (query === "" ? "" : "?" + query), {
        method: target.method ?? "GET",
        credentials: "include",
        headers: ask.body === undefined ? headers : { ...headers, "Content-Type": "application/json" },
        body: ask.body === undefined ? undefined : JSON.stringify(ask.body),
      });
    }
    const body: Record<string, unknown> = {};
    for (const [name, value] of Object.entries(ask.parameters ?? {})) {
      if (target.path.includes("{" + name + "}")) {
        body[target.wire?.[name] ?? name] = value;
      }
    }
    Object.assign(body, dxlibQuery(ask.query ?? {}, ask.list), ask.body ?? {});
    const url = service + "/" + target.operation;
    if (target.handshake === undefined) {
      return send(url, { method: "POST", credentials: "include", headers: { ...headers, "Content-Type": "application/json" }, body: JSON.stringify(body) });
    }
    const download = target.stream === "download";
    const once = await sealed(target.handshake, url, body, headers, false, download);
    if (!once.refresh) {
      return once.response;
    }
    return (await sealed(target.handshake, url, body, headers, true, download)).response;
  }

  async function upload(target: Target, file: Blob | ReadableStream<Uint8Array>, ask: Ask = {}): Promise<Response> {
    if (target.handshake !== undefined) {
      throw new Error(`${target.operation} streams an upload in the envelope of handshake ${target.handshake}, and an upload's body is the file, which no envelope carries (ADR-145)`);
    }
    const headers: Record<string, string> = { Accept: "application/json, application/problem+json", ...(ask.headers ?? {}), "Content-Type": target.mediaType ?? "application/octet-stream" };
    let url: string;
    if (settings.dialect === "standard") {
      const query = new URLSearchParams(ask.query ?? {}).toString();
      url = service + fill(target.path, ask.parameters ?? {}) + (query === "" ? "" : "?" + query);
    } else {
      const values: Record<string, unknown> = {};
      for (const [name, value] of Object.entries(ask.parameters ?? {})) {
        if (target.path.includes("{" + name + "}")) {
          values[target.wire?.[name] ?? name] = value;
        }
      }
      Object.assign(values, ask.query ?? {}, ask.body ?? {});
      if (Object.keys(values).length > 0) {
        headers["X-Var"] = JSON.stringify(values);
      }
      url = service + "/" + target.operation;
    }
    // A stream as a body needs half duplex; a Blob is read as it is sent and needs nothing.
    const init: RequestInit & { duplex?: "half" } = { method: settings.dialect === "standard" ? (target.method ?? "POST") : "POST", credentials: "include", headers, body: file };
    if (!(file instanceof Blob)) {
      init.duplex = "half";
    }
    return send(url, init);
  }

  return { call, upload };
}
